module adder_pipe_64bit(
    input clk,
    input rst_n,
    input i_en,
    input [63:0] adda,
    input [63:0] addb,
    output [64:0] result,
    output o_en
);

    reg [15:0] reg_a[3:0];
    reg [15:0] reg_b[3:0];
    reg [16:0] sum[3:0];
    reg o_en_reg;

    genvar i;
    generate
        for (i = 0; i < 4; i = i + 1) begin
            always @(posedge clk or negedge rst_n) begin
                if (!rst_n) begin
                    reg_a[i] <= 16'b0;
                    reg_b[i] <= 16'b0;
                    sum[i] <= 17'b0;
                end
                else if (i_en) begin
                    reg_a[i] <= adda[15:0 + 16*i];
                    reg_b[i] <= addb[15:0 + 16*i];
                    sum[i] <= {1'b0, reg_a[i]} + {1'b0, reg_b[i]};
                end
            end
        end
    endgenerate

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            o_en_reg <= 1'b0;
        end
        else if (i_en) begin
            o_en_reg <= 1'b1;
        end
        else begin
            o_en_reg <= 1'b0;
        end
    end

    assign result = {sum[3][16:0], sum[2][16:0], sum[1][16:0], sum[0][16:0]};
    assign o_en = o_en_reg;

endmodule
